sys_script_include.script:
var AgendamentoUtils = Class.create();
AgendamentoUtils.prototype = {
    initialize: function() {
    },
	refQualTraining: function(){
		var trainingToBeShown = [];
		var myCourses = {};
		var concludedCourses=[];
		var myTrainings = [];
		var grEnrollments = new GlideRecord("x_1593175_agenda_0_enrollment");
		grEnrollments.addEncodedQuery("studentDYNAMIC90d1921e5f510100a9ad2572f2b477fe");
		grEnrollments.query();
		while(grEnrollments.next()){
			if(grEnrollments.state.toString()=='3' || grEnrollments.state.toString()=='2'){
				if(!myCourses[grEnrollments.training.course.sys_id.toString()]){
				myCourses[grEnrollments.training.course.sys_id.toString()]=0;
			}
			myCourses[grEnrollments.training.course.sys_id.toString()]++;
			}
			myTrainings.push(grEnrollments.training.sys_id.toString());
		}
		for(key in myCourses){
			if(myCourses[key]>=3){
				concludedCourses.push(key);
			}
		}
		var grTrainings = new GlideRecord("x_1593175_agenda_0_training");
		grTrainings.addEncodedQuery("day>javascript:gs.endOfToday()");
		grTrainings.query();
		while(grTrainings.next()){
			var grEnrollments2 = new GlideRecord("x_1593175_agenda_0_enrollment");
			grEnrollments2.addQuery("training.sys_id",grTrainings.sys_id.toString());
			grEnrollments2.addQuery("state","!=","4");
			grEnrollments2.query();
			var enrollmentArr = [];
			while(grEnrollments2.next()){
				enrollmentArr.push(grEnrollments2);
			}
			if(!myTrainings.includes(grTrainings.sys_id.toString()) && !concludedCourses.includes(grTrainings.course.sys_id.toString()) && grTrainings.teacher.sys_id.toString() != gs.getUserID().toString()
			&& grTrainings.spots > enrollmentArr.length ){
				trainingToBeShown.push(grTrainings.sys_id.toString());
			}
		}
		return "sys_idIN" + trainingToBeShown.join(",");
	},
    type: 'AgendamentoUtils'
};
